                "type": [
                  "string",
                  "null"
                ]
              },
              "sourceArtifactItemIds": {
                "type": [
                  "array",
                  "null"
                ],
                "items": {
                  "type": "string"
                }
              },
              "assumptions": {
                "type": [
                  "array",
                  "null"
                ],
                "items": {
                  "type": "string"
                }
              },
              "rationale": {
                "type": [
